namespace Bleksak\MagoPdoExtension\Sql\MySql\Context {
	use Antlr\Antlr4\Runtime\ParserRuleContext;
	use Antlr\Antlr4\Runtime\Token;
	use Antlr\Antlr4\Runtime\Tree\ParseTreeVisitor;
	use Antlr\Antlr4\Runtime\Tree\TerminalNode;
	use Antlr\Antlr4\Runtime\Tree\ParseTreeListener;
	use Bleksak\MagoPdoExtension\Sql\MySql\MySQLParser;
	use Bleksak\MagoPdoExtension\Sql\MySql\MySQLParserListener;

	class QueriesContext extends ParserRuleContext
	{
		public function __construct(?ParserRuleContext $parent, ?int $invokingState = null)
		{
			parent::__construct($parent, $invokingState);
		}

		public function getRuleIndex(): int
		{
		    return MySQLParser::RULE_queries;
	    }

	    public function EOF(): ?TerminalNode
	    {
	        return $this->getToken(MySQLParser::EOF, 0);
	    }

	    /**
	     * @return array<QueryContext>|QueryContext|null
	     */
	    public function query(?int $index = null)
	    {
